#include <cassert>
#include <iterator>
#include <memory>
#include <string>
#include <vector>

int main()
{
    using binary_search_tree::binary_tree;

    std::unique_ptr<binary_tree<int>> tree(new binary_tree<int>(4));
    for (int value : {2, 6, 3, 1, 5, 7, 4, 4}) {
        tree->insert(value);
    }

    assert(tree->data() == 4);
    assert(tree->left()->data() == 2);
    assert(tree->right()->data() == 6);
    assert(tree->left()->right()->data() == 3);
    assert(tree->left()->left()->data() == 1);
    assert(tree->right()->left()->data() == 5);
    assert(tree->right()->right()->data() == 7);
    assert(tree->left()->left()->left() == nullptr);
    assert(tree->left()->left()->right() == nullptr);

    const std::vector<int> expected{1, 2, 3, 4, 4, 4, 5, 6, 7};
    std::vector<int> actual(tree->begin(), tree->end());
    assert(actual == expected);
    assert(std::is_sorted(actual.begin(), actual.end()));

    const binary_tree<int>& const_tree = *tree;
    std::vector<int> const_actual(const_tree.begin(), const_tree.end());
    assert(const_actual == expected);
    std::vector<int> cactual(const_tree.cbegin(), const_tree.cend());
    assert(cactual == expected);

    auto it = tree->begin();
    auto old = it++;
    assert(*old == 1);
    assert(*it == 2);
    assert(it.operator->() != nullptr);
    assert(std::distance(tree->begin(), tree->end()) == static_cast<std::ptrdiff_t>(expected.size()));

    std::unique_ptr<binary_tree<std::string>> strings(new binary_tree<std::string>("m"));
    for (const std::string& value : {"a", "z", "b", "m", "a"}) {
        strings->insert(value);
    }
    const std::vector<std::string> expected_strings{"a", "a", "b", "m", "m", "z"};
    std::vector<std::string> actual_strings(strings->begin(), strings->end());
    assert(actual_strings == expected_strings);

    return 0;
}
